using ClosedXML.Excel; using HTBAM.Api.Support; using HTBAM.Application.Interfaces; using HTBAM.Infrastructure.Data; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using QuestPDF.Fluent; using QuestPDF.Helpers; using QuestPDF.Infrastructure;
namespace HTBAM.Api.Controllers;
[ApiController,Authorize,Route("api/reports")]
public sealed class ReportsController(AppDbContext db,IAutoCommentService autoComments):ControllerBase
{
 [HttpGet("sessions/{id:long}")]public async Task<ActionResult> Session(long id,CancellationToken ct){if(!await AccessScope.CanAccessSessionAsync(db,User,id,ct))return Forbid();return Ok(await BuildSession(id,ct));}
 [HttpGet("students/{id:long}")]public async Task<ActionResult> Student(long id,[FromQuery]DateTime? from,[FromQuery]DateTime? to,CancellationToken ct){var student=await db.StudentsSet.AsNoTracking().FirstOrDefaultAsync(x=>x.Id==id,ct);if(student is null)return NotFound();var sq=db.SessionsSet.AsNoTracking().AsQueryable();if(User.IsInRole("LECTURER")){var tid=await AccessScope.TeacherIdAsync(db,User,ct);sq=sq.Where(x=>x.ClassSection.TeacherId==tid);}if(from!=null)sq=sq.Where(x=>x.ScheduledStart>=from);if(to!=null)sq=sq.Where(x=>x.ScheduledStart<to);var ids=sq.Select(x=>x.Id);var summaries=await db.StudentSessionSummariesSet.AsNoTracking().Where(x=>x.StudentId==id&&ids.Contains(x.SessionId)).Join(db.SessionsSet,x=>x.SessionId,s=>s.Id,(x,s)=>new{x.SessionId,s.ScheduledStart,s.ClassSectionId,x.FocusedRatio,x.DistractedRatio,x.SleepyRatio,x.ActiveRatio,x.AlertCount,x.AlertDurationSeconds,x.ObservationQuality,x.AutoComment,x.AutoCommentProvider,x.AutoCommentGeneratedAt}).OrderByDescending(x=>x.ScheduledStart).ToListAsync(ct);var attendance=await db.AttendanceSet.AsNoTracking().Where(x=>x.StudentId==id&&ids.Contains(x.SessionId)).ToListAsync(ct);var totalObserved=attendance.Sum(x=>x.ObservedSeconds);var averageAttendance=attendance.Count==0?0:attendance.Average(x=>x.Score);return Ok(new{student=new{student.Id,student.StudentCode,student.FullName,student.Email},summary=new{SessionCount=summaries.Count,AverageFocused=summaries.Count==0?0:summaries.Average(x=>x.FocusedRatio),AverageDistracted=summaries.Count==0?0:summaries.Average(x=>x.DistractedRatio),AverageSleepy=summaries.Count==0?0:summaries.Average(x=>x.SleepyRatio),AverageActive=summaries.Count==0?0:summaries.Average(x=>x.ActiveRatio),AverageAttendanceScore=averageAttendance,TotalObservedSeconds=totalObserved,TotalAlerts=summaries.Sum(x=>x.AlertCount)},sessions=summaries,attendance});}
 [HttpGet("class-sections/{id:long}")]public async Task<ActionResult> Class(long id,[FromQuery]DateTime? from,[FromQuery]DateTime? to,CancellationToken ct){if(!await AccessScope.CanAccessClassAsync(db,User,id,ct))return Forbid();var cls=await db.ClassSections.AsNoTracking().Include(x=>x.Course).Include(x=>x.Teacher).FirstOrDefaultAsync(x=>x.Id==id,ct);if(cls is null)return NotFound();var q=db.SessionsSet.AsNoTracking().Where(x=>x.ClassSectionId==id&&x.Status=="COMPLETED");if(from!=null)q=q.Where(x=>x.ScheduledStart>=from);if(to!=null)q=q.Where(x=>x.ScheduledStart<to);var sessionIds=q.Select(x=>x.Id);var timelines=await db.ClassSessionSummariesSet.AsNoTracking().Where(x=>sessionIds.Contains(x.SessionId)).Join(db.SessionsSet,s=>s.SessionId,x=>x.Id,(s,x)=>new{s.SessionId,x.ScheduledStart,s.ObservedStudentCount,s.FocusedRatio,s.DistractedRatio,s.SleepyRatio,s.ActiveRatio,s.AlertCount,s.CameraAiQuality,s.AutoComment,s.AutoCommentProvider,s.AutoCommentGeneratedAt}).OrderBy(x=>x.ScheduledStart).ToListAsync(ct);var studentAgg=await db.StudentSessionSummariesSet.AsNoTracking().Where(x=>sessionIds.Contains(x.SessionId)).GroupBy(x=>x.StudentId).Select(g=>new{StudentId=g.Key,Focused=g.Average(x=>x.FocusedRatio),Distracted=g.Average(x=>x.DistractedRatio),Sleepy=g.Average(x=>x.SleepyRatio),Active=g.Average(x=>x.ActiveRatio),Alerts=g.Sum(x=>x.AlertCount),Quality=g.Average(x=>x.ObservationQuality)}).Join(db.StudentsSet,x=>x.StudentId,s=>s.Id,(x,s)=>new{x.StudentId,s.StudentCode,s.FullName,x.Focused,x.Distracted,x.Sleepy,x.Active,x.Alerts,x.Quality,NeedsAttention=x.Distracted>=0.30m||x.Sleepy>=0.15m||x.Alerts>=3}).OrderByDescending(x=>x.NeedsAttention).ThenByDescending(x=>x.Distracted).ToListAsync(ct);return Ok(new{classSection=new{cls.Id,cls.Code,cls.Name,Course=cls.Course.Name,Teacher=cls.Teacher.FullName,cls.Semester,cls.AcademicYear,cls.AutoComment,cls.AutoCommentProvider,cls.AutoCommentGeneratedAt},summary=new{SessionCount=timelines.Count,Focused=timelines.Count==0?0:timelines.Average(x=>x.FocusedRatio),Distracted=timelines.Count==0?0:timelines.Average(x=>x.DistractedRatio),Sleepy=timelines.Count==0?0:timelines.Average(x=>x.SleepyRatio),Active=timelines.Count==0?0:timelines.Average(x=>x.ActiveRatio),Alerts=timelines.Sum(x=>x.AlertCount)},timeline=timelines,students=studentAgg,attention=studentAgg.Where(x=>x.NeedsAttention).ToList()});}

 [HttpPost("sessions/{id:long}/auto-comment"),Authorize(Roles="ADMIN,LECTURER")]public async Task<ActionResult> GenerateSessionComment(long id,CancellationToken ct){if(!await AccessScope.CanAccessSessionAsync(db,User,id,ct))return Forbid();var result=await autoComments.GenerateSessionAsync(id,UserContext.Id(User),ct);return result is null?Conflict("Session chưa có summary."):Ok(result);}
 [HttpPost("sessions/{sessionId:long}/students/{studentId:long}/auto-comment"),Authorize(Roles="ADMIN,LECTURER")]public async Task<ActionResult> GenerateStudentComment(long sessionId,long studentId,CancellationToken ct){if(!await AccessScope.CanAccessSessionAsync(db,User,sessionId,ct))return Forbid();var result=await autoComments.GenerateStudentAsync(sessionId,studentId,UserContext.Id(User),ct);return result is null?Conflict("Chưa có summary sinh viên."):Ok(result);}
 [HttpPost("class-sections/{id:long}/auto-comment"),Authorize(Roles="ADMIN,LECTURER")]public async Task<ActionResult> GenerateClassSectionComment(long id,CancellationToken ct){if(!await AccessScope.CanAccessClassAsync(db,User,id,ct))return Forbid();var result=await autoComments.GenerateClassSectionAsync(id,UserContext.Id(User),ct);return result is null?Conflict("Lớp chưa có summary từ buổi học đã hoàn thành."):Ok(result);}

 [HttpGet("sessions/{id:long}/excel")]public async Task<IActionResult> SessionExcel(long id,CancellationToken ct){if(!await AccessScope.CanAccessSessionAsync(db,User,id,ct))return Forbid();var report=await BuildSession(id,ct);var bytes=BuildSessionExcel(report);return File(bytes,"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",$"HTBAM-Session-{id}.xlsx");}
 [HttpGet("sessions/{id:long}/pdf")]public async Task<IActionResult> SessionPdf(long id,CancellationToken ct){if(!await AccessScope.CanAccessSessionAsync(db,User,id,ct))return Forbid();var report=await BuildSession(id,ct);return File(BuildSessionPdf(report),"application/pdf",$"HTBAM-Session-{id}.pdf");}
 [HttpGet("students/{id:long}/excel")]public async Task<IActionResult> StudentExcel(long id,CancellationToken ct){var student=await db.StudentsSet.AsNoTracking().FirstOrDefaultAsync(x=>x.Id==id,ct);if(student is null)return NotFound();var sq=db.SessionsSet.AsNoTracking().AsQueryable();if(User.IsInRole("LECTURER")){var tid=await AccessScope.TeacherIdAsync(db,User,ct);sq=sq.Where(x=>x.ClassSection.TeacherId==tid);}var ids=sq.Select(x=>x.Id);var sums=await db.StudentSessionSummariesSet.AsNoTracking().Where(x=>x.StudentId==id&&ids.Contains(x.SessionId)).Join(db.SessionsSet,x=>x.SessionId,s=>s.Id,(x,s)=>new{x.SessionId,s.ScheduledStart,x.FocusedRatio,x.DistractedRatio,x.SleepyRatio,x.ActiveRatio,x.AlertCount,x.ObservationQuality}).OrderBy(x=>x.ScheduledStart).ToListAsync(ct);var atts=await db.AttendanceSet.AsNoTracking().Where(x=>x.StudentId==id&&ids.Contains(x.SessionId)).ToDictionaryAsync(x=>x.SessionId,ct);using var wb=new XLWorkbook();var ws=wb.Worksheets.Add("Student");ws.Cell(1,1).Value="MSSV";ws.Cell(1,2).Value=student.StudentCode;ws.Cell(2,1).Value="Họ tên";ws.Cell(2,2).Value=student.FullName;string[] h={"SessionId","ScheduledStart","Focused","Distracted","Sleepy","Active","Alerts","Quality","AttendanceStatus","AttendanceScore"};for(int i=0;i<h.Length;i++)ws.Cell(4,i+1).Value=h[i];var row=5;foreach(var x in sums){atts.TryGetValue(x.SessionId,out var a);ws.Cell(row,1).Value=x.SessionId;ws.Cell(row,2).Value=x.ScheduledStart;ws.Cell(row,3).Value=x.FocusedRatio;ws.Cell(row,4).Value=x.DistractedRatio;ws.Cell(row,5).Value=x.SleepyRatio;ws.Cell(row,6).Value=x.ActiveRatio;ws.Cell(row,7).Value=x.AlertCount;ws.Cell(row,8).Value=x.ObservationQuality;ws.Cell(row,9).Value=a?.Status??"";ws.Cell(row,10).Value=a?.Score??0;row++;}ws.Columns().AdjustToContents();using var ms=new MemoryStream();wb.SaveAs(ms);return File(ms.ToArray(),"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",$"HTBAM-Student-{student.StudentCode}.xlsx");}
 [HttpGet("students/{id:long}/pdf")]public async Task<IActionResult> StudentPdf(long id,CancellationToken ct){var student=await db.StudentsSet.AsNoTracking().FirstOrDefaultAsync(x=>x.Id==id,ct);if(student is null)return NotFound();var sq=db.SessionsSet.AsNoTracking().AsQueryable();if(User.IsInRole("LECTURER")){var tid=await AccessScope.TeacherIdAsync(db,User,ct);sq=sq.Where(x=>x.ClassSection.TeacherId==tid);}var ids=sq.Select(x=>x.Id);var sums=await db.StudentSessionSummariesSet.AsNoTracking().Where(x=>x.StudentId==id&&ids.Contains(x.SessionId)).ToListAsync(ct);var atts=await db.AttendanceSet.AsNoTracking().Where(x=>x.StudentId==id&&ids.Contains(x.SessionId)).ToListAsync(ct);var pdf=Document.Create(c=>c.Page(p=>{p.Size(PageSizes.A4);p.Margin(32);p.DefaultTextStyle(x=>x.FontSize(10));p.Header().Text($"HTBAM - Báo cáo sinh viên {student.StudentCode}").Bold().FontSize(18);p.Content().Column(col=>{col.Spacing(6);col.Item().Text(student.FullName);col.Item().Text($"Số buổi có summary: {sums.Count}");col.Item().Text($"Focused TB: {(sums.Count==0?0:sums.Average(x=>x.FocusedRatio)):P1}");col.Item().Text($"Distracted TB: {(sums.Count==0?0:sums.Average(x=>x.DistractedRatio)):P1}");col.Item().Text($"Sleepy TB: {(sums.Count==0?0:sums.Average(x=>x.SleepyRatio)):P1}");col.Item().Text($"Active TB: {(sums.Count==0?0:sums.Average(x=>x.ActiveRatio)):P1}");col.Item().Text($"Điểm chuyên cần TB: {(atts.Count==0?0:atts.Average(x=>x.Score)):0.00}");});p.Footer().AlignCenter().Text(x=>{x.Span("Trang ");x.CurrentPageNumber();});})).GeneratePdf();return File(pdf,"application/pdf",$"HTBAM-Student-{student.StudentCode}.pdf");}
 // Hai endpoint dưới dùng bảng dữ liệu phẳng để tránh phụ thuộc model/LLM.
 [HttpGet("class-sections/{id:long}/excel")]public async Task<IActionResult> ClassExcel(long id,CancellationToken ct){if(!await AccessScope.CanAccessClassAsync(db,User,id,ct))return Forbid();var sessions=await db.SessionsSet.AsNoTracking().Where(x=>x.ClassSectionId==id).OrderBy(x=>x.ScheduledStart).ToListAsync(ct);using var wb=new XLWorkbook();var ws=wb.Worksheets.Add("Sessions");ws.Cell(1,1).Value="SessionId";ws.Cell(1,2).Value="ScheduledStart";ws.Cell(1,3).Value="Status";ws.Cell(1,4).Value="Focused";ws.Cell(1,5).Value="Distracted";ws.Cell(1,6).Value="Sleepy";ws.Cell(1,7).Value="Active";var row=2;foreach(var s in sessions){var sum=await db.ClassSessionSummariesSet.AsNoTracking().FirstOrDefaultAsync(x=>x.SessionId==s.Id,ct);ws.Cell(row,1).Value=s.Id;ws.Cell(row,2).Value=s.ScheduledStart;ws.Cell(row,3).Value=s.Status;ws.Cell(row,4).Value=sum?.FocusedRatio??0;ws.Cell(row,5).Value=sum?.DistractedRatio??0;ws.Cell(row,6).Value=sum?.SleepyRatio??0;ws.Cell(row,7).Value=sum?.ActiveRatio??0;row++;}ws.Columns().AdjustToContents();using var ms=new MemoryStream();wb.SaveAs(ms);return File(ms.ToArray(),"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",$"HTBAM-Class-{id}.xlsx");}
 [HttpGet("class-sections/{id:long}/pdf")]public async Task<IActionResult> ClassPdf(long id,CancellationToken ct){if(!await AccessScope.CanAccessClassAsync(db,User,id,ct))return Forbid();var cls=await db.ClassSections.AsNoTracking().FirstOrDefaultAsync(x=>x.Id==id,ct);if(cls is null)return NotFound();var sums=await db.ClassSessionSummariesSet.AsNoTracking().Where(x=>db.SessionsSet.Where(s=>s.ClassSectionId==id).Select(s=>s.Id).Contains(x.SessionId)).ToListAsync(ct);var pdf=Document.Create(c=>c.Page(p=>{p.Size(PageSizes.A4);p.Margin(32);p.DefaultTextStyle(x=>x.FontSize(10));p.Header().Text($"HTBAM - Báo cáo lớp {cls.Code}").Bold().FontSize(18);p.Content().Column(col=>{col.Spacing(8);col.Item().Text($"Số buổi có dữ liệu: {sums.Count}");col.Item().Text($"Focused TB: {(sums.Count==0?0:sums.Average(x=>x.FocusedRatio)):P1}");col.Item().Text($"Distracted TB: {(sums.Count==0?0:sums.Average(x=>x.DistractedRatio)):P1}");col.Item().Text($"Sleepy TB: {(sums.Count==0?0:sums.Average(x=>x.SleepyRatio)):P1}");col.Item().Text($"Active TB: {(sums.Count==0?0:sums.Average(x=>x.ActiveRatio)):P1}");});p.Footer().AlignCenter().Text(x=>{x.Span("Trang ");x.CurrentPageNumber();});})).GeneratePdf();return File(pdf,"application/pdf",$"HTBAM-Class-{id}.pdf");}

 private async Task<object> BuildSession(long id,CancellationToken ct){var session=await db.SessionsSet.AsNoTracking().Include(x=>x.ClassSection).ThenInclude(x=>x.Course).Include(x=>x.ClassSection).ThenInclude(x=>x.Teacher).FirstOrDefaultAsync(x=>x.Id==id,ct)??throw new KeyNotFoundException("Session không tồn tại.");var cls=await db.ClassSessionSummariesSet.AsNoTracking().FirstOrDefaultAsync(x=>x.SessionId==id,ct);var students=await db.StudentSessionSummariesSet.AsNoTracking().Where(x=>x.SessionId==id).Join(db.StudentsSet,x=>x.StudentId,s=>s.Id,(x,s)=>new{x.StudentId,s.StudentCode,s.FullName,x.FocusedRatio,x.DistractedRatio,x.SleepyRatio,x.ActiveRatio,x.AlertCount,x.AlertDurationSeconds,x.ObservationQuality,x.AutoComment,x.AutoCommentProvider,x.AutoCommentGeneratedAt}).OrderBy(x=>x.StudentCode).ToListAsync(ct);var attendance=await db.AttendanceSet.AsNoTracking().Where(x=>x.SessionId==id).ToListAsync(ct);var timeline=await db.BehaviorEventsSet.AsNoTracking().Where(x=>x.SessionId==id).OrderBy(x=>x.StartedAt).Take(10000).ToListAsync(ct);var alerts=await db.AlertsSet.AsNoTracking().Where(x=>x.SessionId==id).OrderBy(x=>x.StartedAt).ToListAsync(ct);var attention=students.Where(x=>x.DistractedRatio>=.30m||x.SleepyRatio>=.15m||x.AlertCount>=3).ToList();return new{session=new{session.Id,session.ClassSectionId,ClassSection=session.ClassSection.Code,Course=session.ClassSection.Course.Name,Teacher=session.ClassSection.Teacher.FullName,session.ScheduledStart,session.StartedAt,session.EndedAt,session.Status,session.LecturerComment},summary=cls,students,attendance,timeline,alerts,attention};}
 private static byte[] BuildSessionExcel(object report){dynamic r=report;using var wb=new XLWorkbook();var ws=wb.Worksheets.Add("Overview");ws.Cell("A1").Value="HTBAM SESSION REPORT";ws.Cell("A3").Value="Session";ws.Cell("B3").Value=(long)r.session.Id;ws.Cell("A4").Value="Class";ws.Cell("B4").Value=(string)r.session.ClassSection;ws.Cell("A5").Value="Course";ws.Cell("B5").Value=(string)r.session.Course;var students=wb.Worksheets.Add("Students");string[] heads={"StudentCode","FullName","Focused","Distracted","Sleepy","Active","Alerts","Quality"};for(var i=0;i<heads.Length;i++)students.Cell(1,i+1).Value=heads[i];var row=2;foreach(var s in r.students){students.Cell(row,1).Value=(string)s.StudentCode;students.Cell(row,2).Value=(string)s.FullName;students.Cell(row,3).Value=(decimal)s.FocusedRatio;students.Cell(row,4).Value=(decimal)s.DistractedRatio;students.Cell(row,5).Value=(decimal)s.SleepyRatio;students.Cell(row,6).Value=(decimal)s.ActiveRatio;students.Cell(row,7).Value=(int)s.AlertCount;students.Cell(row,8).Value=(decimal)s.ObservationQuality;row++;}students.Columns().AdjustToContents();using var ms=new MemoryStream();wb.SaveAs(ms);return ms.ToArray();}
 private static byte[] BuildSessionPdf(object report){dynamic r=report;return Document.Create(c=>c.Page(p=>{p.Size(PageSizes.A4);p.Margin(32);p.DefaultTextStyle(x=>x.FontSize(10));p.Header().Text($"HTBAM - Session #{r.session.Id}").Bold().FontSize(18);p.Content().Column(col=>{col.Spacing(6);col.Item().Text($"Lớp: {r.session.ClassSection}");col.Item().Text($"Môn: {r.session.Course}");col.Item().Text($"Giảng viên: {r.session.Teacher}");if(r.summary!=null){col.Item().Text($"Focused: {r.summary.FocusedRatio:P1}");col.Item().Text($"Distracted: {r.summary.DistractedRatio:P1}");col.Item().Text($"Sleepy: {r.summary.SleepyRatio:P1}");col.Item().Text($"Active: {r.summary.ActiveRatio:P1}");col.Item().Text($"Alerts: {r.summary.AlertCount}");}});p.Footer().AlignCenter().Text(x=>{x.Span("Trang ");x.CurrentPageNumber();});})).GeneratePdf();}
}
